/// A marker component attached to the entity of VRM.
/// This component is automatically inserted after the [`VrmHandle`](crate::prelude::VrmHandle) is loaded.
#[derive(Debug, Component, Reflect, Copy, Clone)]
#[reflect(Component)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", reflect(Serialize, Deserialize))]
pub struct Vrm;

impl Vrm {
    pub const EXPRESSIONS_ROOT: &'static str = "VRMC_vrm.expressions";
    pub const ROOT_BONE: &'static str = "VRMC_vrm.root_bone";
}

/// Coordinate basis applied to the loaded model scene.
#[derive(Debug, Component, Copy, Clone, PartialEq, Eq)]
pub struct VrmCoordinateBasis(pub CoordinateBasis);

/// Source-generation compatibility diagnostics owned by one VRM root.
#[derive(Debug, Component, Clone, PartialEq)]
pub struct VrmCompatibilityDiagnostics {
    /// Generation selected by the runtime normalization boundary.
    pub generation: VrmGeneration,
    /// Source-only VRM 0.x metadata, if applicable.
    pub legacy_meta: Option<Vrm0MetaDiagnostics>,
    /// Non-fatal warnings scoped to this root.
    pub warnings: Vec<VrmCompatibilityWarning>,
}

/// Source glTF node index attached to every instantiated scene node.
///
/// VRM 0.x uses mesh indices in several extension arrays and permits duplicate
/// node names. Runtime registries therefore resolve by this identity rather
/// than by the display name generated by the glTF loader.
#[derive(Debug, Component, Reflect, Copy, Clone, PartialEq, Eq)]
#[reflect(Component)]
pub struct VrmNodeIndex(pub usize);

/// Child entity that owns the one-time VRM 0.x Y=pi coordinate basis.
#[derive(Debug, Component, Reflect, Copy, Clone)]
#[reflect(Component)]
pub struct VrmBasisRoot;

impl VrmCoordinateBasis {
    /// Returns the one root transform used for the model generation.
    #[must_use]
    pub fn transform(self) -> Option<Transform> {
        match self.0 {
            CoordinateBasis::Vrm0Y180 => Some(Transform::from_rotation(Quat::from_rotation_y(
                std::f32::consts::PI,
            ))),
            CoordinateBasis::Vrm1Identity => None,
        }
    }
}

#[cfg(test)]
mod coordinate_basis_tests {
    use super::*;
    use bevy::prelude::ChildOf;

    #[test]
    fn legacy_basis_is_the_only_generation_rotation() {
        let legacy = VrmCoordinateBasis(CoordinateBasis::Vrm0Y180)
            .transform()
            .expect("legacy VRM requires a basis transform");
        let expected = Quat::from_rotation_y(std::f32::consts::PI);
        assert!(legacy.rotation.dot(expected).abs() > 0.999_999);
        assert!(
            VrmCoordinateBasis(CoordinateBasis::Vrm1Identity)
                .transform()
                .is_none()
        );
    }

    #[test]
    fn legacy_basis_maps_source_front_to_canonical_front_without_reflection() {
        let basis = VrmCoordinateBasis(CoordinateBasis::Vrm0Y180)
            .transform()
            .expect("legacy VRM requires a basis transform");

        assert!((basis.rotation * Vec3::NEG_Z - Vec3::Z).length() < 1.0e-5);
        assert!((basis.rotation * Vec3::Y - Vec3::Y).length() < 1.0e-5);
        assert!(Mat3::from_quat(basis.rotation).determinant() > 0.0);
    }

    #[test]
    fn legacy_basis_is_a_child_and_keeps_application_root_identity() {
        let mut world = World::new();
        let application_root = world
            .spawn((Transform::IDENTITY, GlobalTransform::IDENTITY, Vrm))
            .id();
        let basis = world
            .spawn((
                VrmBasisRoot,
                VrmCoordinateBasis(CoordinateBasis::Vrm0Y180)
                    .transform()
                    .expect("legacy basis exists"),
                ChildOf(application_root),
            ))
            .id();

        assert_eq!(
            world.get::<Transform>(application_root).unwrap().rotation,
            Quat::IDENTITY
        );
        assert_eq!(
            world.get::<ChildOf>(basis).unwrap().parent(),
            application_root
        );
        assert!(
            world
                .get::<Transform>(basis)
                .unwrap()
                .rotation
                .dot(Quat::from_rotation_y(std::f32::consts::PI))
                .abs()
                > 0.999_999
        );
    }
}

/// The path to the VRM file.
/// This component is automatically inserted after the [`VrmHandle`](crate::prelude::VrmHandle) is loaded.
#[derive(Debug, Reflect, Clone, Component)]
#[reflect(Component)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", reflect(Serialize, Deserialize))]
pub struct VrmPath(pub PathBuf);

impl VrmPath {
    /// Creates a new [`VrmPath`] from the path.
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self(path.into())
    }
}

/// The bone's initial transform.
#[derive(Debug, Copy, Clone, Component, Deref, Reflect, Default)]
#[reflect(Component)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", reflect(Serialize, Deserialize))]
pub struct RestTransform(pub Transform);

/// The bone's initial global transform.
#[derive(Debug, Copy, Clone, Component, Deref, Reflect, Default)]
#[reflect(Component)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", reflect(Serialize, Deserialize))]
pub struct RestGlobalTransform(pub GlobalTransform);

marker_component!(
    /// A marker component attached to the entity of VRM.
    /// This component is automatically inserted after the [`VrmHandle`](crate::prelude::VrmHandle) is loaded.
    Initialized
);
/// The main plugin for VRM support in Bevy.
///
/// Please refer to [`VrmHandle`](crate::prelude::VrmHandle) for more details.
pub struct VrmPlugin;

impl Plugin for VrmPlugin {
    fn build(
        &self,
        app: &mut App,
    ) {
        app.init_asset::<VrmAsset>().add_plugins((
            VrmLoaderPlugin,
            VrmInitializePlugin,
            VrmDetachPlugin,
            VrmSpringBonePlugin,
            VrmHumanoidBonePlugin,
            VrmExpressionPlugin,
            VrmNodeConstraintPlugin,
            MtoonMaterialPlugin,
            LookAtPlugin,
            BodyTrackingPlugin,
            VrmFirstPersonPlugin,
        ));

        app.configure_sets(
            PostUpdate,
            (
                VrmSystemSets::GazeControl,
                VrmSystemSets::Expressions,
                VrmSystemSets::PropagateAfterExpressions,
                VrmSystemSets::Constraints,
                VrmSystemSets::PropagateAfterConstraints,
                VrmSystemSets::SpringBone,
            )
                .chain()
                .after(AnimationSystems),
        );

        // Add manual transform propagation systems to follow VRM spec update order
        // See: https://vrm.dev/api/api_update/
        app.add_systems(
            PostUpdate,
            (sync_simple_transforms, propagate_parent_transforms)
                .chain()
                .in_set(VrmSystemSets::PropagateAfterConstraints)
                .after(VrmSystemSets::Constraints)
                .before(VrmSystemSets::SpringBone),
        );
        app.add_systems(
            PostUpdate,
            (sync_simple_transforms, propagate_parent_transforms)
                .chain()
                .in_set(VrmSystemSets::PropagateAfterExpressions)
                .after(VrmSystemSets::Expressions)
                .before(VrmSystemSets::Constraints),
        );

        app.register_type::<Vrm>()
            .register_type::<VrmPath>()
            .register_type::<RestTransform>()
            .register_type::<RestGlobalTransform>()
            .register_type::<VrmBone>()
            .register_type::<VrmExpression>()
            .register_type::<VrmNodeIndex>()
            .register_type::<VrmBasisRoot>()
            .register_type::<Initialized>();
    }
}
